export const indicators={
 dolar:{name:'Dólar observado',unit:'CLP por USD',symbol:'$',frequency:'daily',explanation:'Expresa cuántos pesos equivale un dólar observado. Es una referencia oficial, distinta del precio de compra o venta de cada banco o casa de cambio.'},
 uf:{name:'UF',unit:'CLP por UF',symbol:'$',frequency:'daily',explanation:'Unidad de cuenta reajustada por inflación. Un contrato en UF cambia su equivalente en pesos según el valor del día.'},
 ipc:{name:'Inflación · IPC',unit:'Variación mensual (%)',symbol:'%',frequency:'monthly',explanation:'Mide el cambio mensual de los precios de una canasta de bienes y servicios. La variación de 12 meses es una medida distinta y se muestra por separado.'},
 tpm:{name:'Tasa de política',unit:'Tasa nominal anual (%)',symbol:'%',frequency:'step',explanation:'Tasa fijada por el Banco Central que orienta las condiciones monetarias. No equivale a la tasa de un crédito personal. El gráfico conserva cada tasa hasta la siguiente decisión.'},
 cobre:{name:'Cobre',unit:'USD por libra',symbol:'US$',frequency:'daily',explanation:'Precio de referencia del cobre por libra. Ayuda a seguir un producto importante para las exportaciones chilenas; no es una cotización de inversión en tiempo real.'},
 imacec:{name:'Imacec',unit:'Variación anual (%)',symbol:'%',frequency:'monthly',explanation:'Compara la actividad económica de un mes con el mismo mes del año anterior. La serie puede revisarse al publicarse nueva información.'}
};
export function chileDay(now=new Date()){return new Intl.DateTimeFormat('en-CA',{timeZone:'America/Santiago',year:'numeric',month:'2-digit',day:'2-digit'}).format(now);}
export function numberLabel(v,id){if(!Number.isFinite(v))return 'Sin dato';const text=new Intl.NumberFormat('es-CL',{maximumFractionDigits:2}).format(v);return indicators[id].symbol==='%'?text+'%':indicators[id].symbol+text;}
export function periodLabel(s){if(!s)return 'Sin fecha';return new Date(s.slice(0,7).length===s.length?s+'-01T12:00:00Z':s+'T12:00:00Z').toLocaleDateString('es-CL',s.length===7?{month:'long',year:'numeric',timeZone:'UTC'}:{day:'numeric',month:'short',year:'numeric',timeZone:'UTC'});}
export function rangeRows(series,months,end,step=false){const finish=new Date(end+'T12:00:00Z'),start=new Date(finish);start.setUTCMonth(start.getUTCMonth()-months);const cutoff=start.toISOString().slice(0,10);let rows=series.filter(r=>r.date>=cutoff&&r.date<=end);if(step){const before=series.filter(r=>r.date<cutoff).at(-1);if(before)rows=[{date:cutoff,value:before.value,carried:true},...rows];if(rows.length&&rows.at(-1).date<end)rows.push({...rows.at(-1),date:end,carried:true});}return rows;}
